"""Matching core for Fish-style Xonsh abbreviations.

This module deliberately has no Xonsh or Prompt Toolkit dependency.  Xonsh's
completion parser supplies :class:`AbbreviationContext` at runtime; keeping the
matcher independent makes its edge cases cheap to exercise with pytest.
"""

from __future__ import annotations

from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, replace
import inspect
from re import Pattern
from typing import Callable, Literal, Match, TypeAlias


@dataclass(frozen=True)
class AbbreviationContext:
    buffer: str
    cursor: int
    token_start: int
    token_end: int
    token: str
    command_path: tuple[str, ...] = ()
    command_position: bool = False
    quoted: bool = False

    @property
    def is_command_position(self) -> bool:
        return self.command_position


@dataclass(frozen=True)
class AbbreviationResult:
    text: str
    cursor: int | None = None
    replace_buffer: bool = False


ExpansionValue: TypeAlias = str | AbbreviationResult
ExpansionCallback: TypeAlias = Callable[
    [AbbreviationContext, Match[str] | None], ExpansionValue | None
]


def completion_match_key(trigger: str, query: str) -> tuple | None:
    """Smart-case subsequence ranking; prefixes always win.

    Find the best alignment, rewarding boundaries and consecutive characters
    while charging for skipped characters. This is inspired by fzf scoring,
    rather than a port of its algorithm. Smaller keys rank first.
    """
    sensitive = any(char.isupper() for char in query)
    text = trigger if sensitive else trigger.lower()
    pattern = query if sensitive else query.lower()
    if not pattern:
        return (0, 0, trigger.lower(), trigger)
    if text.startswith(pattern):
        return (0, 0, trigger.lower(), trigger)

    # For each query character, keep the best score ending at each position.
    # A running maximum makes this O(len(trigger) * len(query)).
    previous: dict[int, int] = {}
    for query_index, char in enumerate(pattern):
        current = {}
        best_gap = None
        for index, candidate in enumerate(text):
            prior = previous.get(index - 2)
            if prior is not None:
                value = prior + index - 2
                best_gap = value if best_gap is None else max(best_gap, value)
            if candidate != char:
                continue
            boundary = (
                index == 0
                or not trigger[index - 1].isalnum()
                or (trigger[index - 1].islower() and trigger[index].isupper())
            )
            bonus = 16 + (12 if boundary else 0)
            if query_index == 0:
                current[index] = bonus - index
                continue
            scores = []
            if index - 1 in previous:
                scores.append(previous[index - 1] + 10)
            if best_gap is not None:
                scores.append(best_gap - index + 1 - 3)
            if scores:
                current[index] = max(scores) + bonus
        if not current:
            return None
        previous = current
    return (1, -max(previous.values()), trigger.lower(), trigger)


@dataclass(frozen=True)
class Abbreviation:
    trigger: str | Pattern[str]
    replacement: ExpansionValue | ExpansionCallback
    position: Literal["command", "anywhere"] = "command"
    commands: tuple[str, ...] = ()
    cursor_marker: str | None = None
    expand_quoted: bool = False
    internal: bool = False
    source_file: str | None = None
    source_line: int | None = None
    reminder: bool = False # marker for reminder abbrs (things I want to learn or use and thus the name is often more verbose)

    @property
    def is_regex(self) -> bool:
        return not isinstance(self.trigger, str)

    def match(self, context: AbbreviationContext) -> Match[str] | bool | None:
        if context.quoted and not self.expand_quoted:
            return None
        # A command scope necessarily targets an argument.  Unscoped Fish
        # abbreviations remain command-position-only unless marked anywhere.
        if (
            self.position == "command"
            and not self.commands
            and not context.is_command_position
        ):
            return None
        if self.commands and context.command_path[: len(self.commands)] != self.commands:
            return None
        if self.is_regex:
            return self.trigger.fullmatch(context.token)
        return self.trigger == context.token

    def completion_key(self, context: AbbreviationContext) -> tuple | None:
        """Score a literal completion while retaining exact expansion rules."""
        if self.internal or self.is_regex:
            return None
        if not self.match(replace(context, token=self.trigger)):
            return None
        return completion_match_key(self.trigger, context.token)

    def expand(
        self, context: AbbreviationContext, match: Match[str] | bool
    ) -> AbbreviationResult | None:
        regex_match = match if not isinstance(match, bool) else None
        value = (
            self.replacement(context, regex_match)
            if callable(self.replacement)
            else self.replacement
        )
        if value is None:
            return None
        result = value if isinstance(value, AbbreviationResult) else AbbreviationResult(value)
        if self.cursor_marker is None:
            return result
        marker_count = result.text.count(self.cursor_marker)
        # Fish puts the cursor at the end when a function returns no marker.
        if marker_count == 0 and callable(self.replacement):
            return AbbreviationResult(
                result.text,
                cursor=result.cursor if result.cursor is not None else len(result.text),
                replace_buffer=result.replace_buffer,
            )
        if marker_count != 1:
            raise ValueError(
                f"abbreviation {self.trigger!r} must contain exactly one "
                f"cursor marker {self.cursor_marker!r}"
            )
        marker_at = result.text.index(self.cursor_marker)
        return AbbreviationResult(
            result.text[:marker_at] + result.text[marker_at + len(self.cursor_marker) :],
            cursor=marker_at,
            replace_buffer=result.replace_buffer,
        )


class AbbreviationRegistry:
    def __init__(self, abbreviations: list[Abbreviation] | None = None):
        self.abbreviations = list(abbreviations or ())

    def add(self, abbreviation: Abbreviation) -> Abbreviation:
        self.abbreviations.append(abbreviation)
        return abbreviation

    @staticmethod
    def _priority(abbreviation: Abbreviation) -> tuple[int, int, int]:
        return (
            not abbreviation.is_regex,
            bool(abbreviation.commands),
            abbreviation.position == "command",
        )

    def applicable(self, context: AbbreviationContext) -> list[Abbreviation]:
        """Return matches in expansion order.

        This is intentionally the one applicability entry point for both the
        keybinding and any future abbreviation suggestions/completions.
        """
        # Stable sorting keeps later registrations first at equal specificity.
        matches = [a for a in reversed(self.abbreviations) if a.match(context)]
        return sorted(matches, key=self._priority, reverse=True)

    def expand(
        self, context: AbbreviationContext
    ) -> tuple[AbbreviationResult, Abbreviation] | None:
        for abbreviation in self.applicable(context):
            match = abbreviation.match(context)
            assert match is not None
            result = abbreviation.expand(context, match)
            if result is not None:
                return result, abbreviation
        return None


def _fish_function_name(replacement: Callable) -> str | None:
    """Return the fish function name wrapped by an ``abbr_from_fish_function``."""
    qualname = getattr(replacement, "__qualname__", type(replacement).__name__)
    if not qualname.startswith("abbr_from_fish_function"):
        return None
    closure = getattr(replacement, "__closure__", None)
    if closure is None:
        return None
    try:
        return closure[0].cell_contents
    except (IndexError, ValueError):
        return None


_FISH_SOURCE_CACHE: dict[str, str] = {}


def _fish_function_source(func_name: str) -> str:
    """Fetch a fish function body, falling back to a descriptive error."""
    cached = _FISH_SOURCE_CACHE.get(func_name)
    if cached is not None:
        return cached
    try:
        # TODO(perf): if this shows up in profiles, consider batching all fish
        #   function lookups into a single fish process invocation (e.g. pass
        #   multiple names to `type` and split on a delimiter marker) to avoid
        #   per-function subprocess spawn overhead entirely.
        from wes_fish_bridge import fish_function_source
        source = fish_function_source(func_name)
    except Exception:
        source = "failed to find fish function source"
    _FISH_SOURCE_CACHE[func_name] = source
    return source


def _callback_qualname(replacement: Callable) -> str:
    return getattr(replacement, "__qualname__", type(replacement).__name__)


def abbreviation_replacement_text(
    abbreviation: Abbreviation, show_fish_functions: bool = False
) -> str:
    """Describe a replacement without executing a dynamic callback."""
    replacement = abbreviation.replacement
    if isinstance(replacement, str):
        return replacement
    if show_fish_functions:
        func_name = _fish_function_name(replacement)
        if func_name is not None:
            return _fish_function_source(func_name)
    return _callback_qualname(replacement)


def abbreviation_replacement_texts(
    abbreviations: list[Abbreviation],
    show_fish_functions: bool = False,
) -> list[str]:
    """Describe many replacements, parallelizing fish source lookups.

    When ``show_fish_functions`` is set, the per-function ``fish type``
    subprocesses run concurrently instead of one after another.
    """
    if not show_fish_functions:
        return [abbreviation_replacement_text(a) for a in abbreviations]

    fish_names: dict[int, str] = {}
    results: list[str | None] = [None] * len(abbreviations)
    for index, abbreviation in enumerate(abbreviations):
        replacement = abbreviation.replacement
        if isinstance(replacement, str):
            results[index] = replacement
            continue
        func_name = _fish_function_name(replacement)
        if func_name is not None:
            fish_names[index] = func_name
        else:
            results[index] = _callback_qualname(replacement)

    if fish_names:
        workers = min(len(fish_names), 8)
        with ThreadPoolExecutor(max_workers=workers) as executor:
            futures = {
                index: executor.submit(_fish_function_source, name)
                for index, name in fish_names.items()
            }
            for index, future in futures.items():
                results[index] = future.result()

    return [
        result if result is not None else "failed to find fish function source"
        for result in results
    ]

# TODO move away from consumers using global XONSH_ABBREVIATIONS and instead just pass None for the registry
#  OR have them import it at least so it is clean where it comes from
#  even if XONSH has one global NS for all modules... I can still insist on only module imports to get globals
XONSH_ABBREVIATIONS = AbbreviationRegistry()

def reset_registry():
    """
    Intended for testing to create a new, yet still global, registry instance
    - to keep a clean registration contract behind a global instance
    """
    global XONSH_ABBREVIATIONS
    XONSH_ABBREVIATIONS = AbbreviationRegistry()
    return XONSH_ABBREVIATIONS


def abbr(trigger, replacement, position: Literal["command", "anywhere"] = "command", **options):
    if "commands" in options:
        commands = options.get("commands")

        if isinstance(<|CURSOR_IS_HERE|>
        # print(f'{options.get("commands")=} {type_of_commands}')
    # TODO pass all all options as named options... and replicage that into reminder_abbr() below
    """Register an abbreviation with declaration syntax close to Fish's."""
    # FYI < 1us per abbr to get source_file/source_line, so this is fine
    caller = inspect.currentframe()
    try:
        caller = caller.f_back if caller is not None else None
        options.setdefault("source_file", caller.f_code.co_filename if caller else None)
        options.setdefault("source_line", caller.f_lineno if caller else None)
    finally:
        del caller

    return XONSH_ABBREVIATIONS.add(Abbreviation(trigger, replacement, position=position, **options))

def reminder_abbr(trigger, replacement, **options):
    options.setdefault("reminder", True)
    return abbr(trigger, replacement, **options)
